import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../context/AuthContext';
import './MascotasReportadas.css'; // Importá el CSS

const MascotasReportadasPage = () => {
  const { user } = useContext(AuthContext);
  const [mascotas, setMascotas] = useState([]);
  const [mascotaEditando, setMascotaEditando] = useState(null); // Estado para la mascota en edición

  useEffect(() => {
    if (user?.id) {
      const fetchMascotas = async () => {
        try {
          const response = await fetch(`http://localhost:3000/api/pets?reporterId=${user.id}`);
          const data = await response.json();
          setMascotas(data);
        } catch (error) {
          console.error('Error al cargar mascotas:', error);
        }
      };

      fetchMascotas();
    }
  }, [user]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await fetch(`http://localhost:3000/api/pets/${mascotaEditando.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: mascotaEditando.name,
          location: mascotaEditando.location,
          // agregá otros campos que quieras editar
        }),
      });
      if (response.ok) {
        const updatedPet = await response.json();
        setMascotas(mascotas.map(m => m.id === updatedPet.id ? updatedPet : m));
        setMascotaEditando(null); // Cerrar el formulario de edición
      } else {
        console.error('Error al actualizar la mascota');
      }
    } catch (error) {
      console.error('Error en la petición:', error);
    }
  };

  return (
    <div className="container">
      <h1 className="tituloMascotaReportadas">Mascotas Reportadas</h1>
      <div className="mascotas-container">
        {mascotas.length > 0 ? (
          mascotas.map((mascota) => (
            <div key={mascota.id} className="mascota-card">
              <img src={mascota.imageurl} alt={mascota.name} className="mascota-image" />
              <div className="mascota-info">
                <h2 className="mascota-name">{mascota.name}</h2>
                <p className="mascota-location">{mascota.location}</p>
                <button className="btn-editar" onClick={() => setMascotaEditando(mascota)}>Editar</button>
              </div>
            </div>
          ))
        ) : (
          <p>No has reportado ninguna mascota aún.</p>
        )}
      </div>

      {/* Formulario de edición */}
      {mascotaEditando && (
        <form onSubmit={handleSubmit} className="form-editar">
          <input 
            type="text" 
            value={mascotaEditando.name} 
            onChange={(e) => setMascotaEditando({...mascotaEditando, name: e.target.value})} 
            placeholder="Nombre de la mascota"
            required
          />
          <input 
            type="text" 
            value={mascotaEditando.location} 
            onChange={(e) => setMascotaEditando({...mascotaEditando, location: e.target.value})} 
            placeholder="Ubicación"
            required
          />
          <button type="submit">Guardar</button>
              <button 
      className="btn-editar" 
      onClick={() => navigate(`/editar-mascota/${mascota.id}`)}
    >
      Editar
    </button>
        </form>
      )}
    </div>
  );
};

export default MascotasReportadasPage;
